#!/usr/bin/env python3
"""
ABRAXAS — FINAL CLEAN BUILD SCRIPT
Run from project root: python3 fix_final_clean.py
Fixes every known build error in one shot.
"""
import base64, os, sys, glob

if not os.path.exists("components"):
    print("Run from project root"); sys.exit(1)

FILES = {
    "lib/solana/program.ts": "",
    "components/IssuanceEngine.tsx": "",
    "components/CertificateDisplay.tsx": "",
    "components/AssetDetailClient.tsx": "",
    "components/LanguageSelector.tsx": "",
    "components/TerminalArena.tsx": "",
    "lib/auth.ts": "",
    "lib/services/bagsService.ts": "",
    "types/next-auth.d.ts": "",
    "tailwind.config.js": "",
    "next.config.js": "",
    ".env.local.example": "",
}

for path, enc in FILES.items():
    d = os.path.dirname(path)
    if d: os.makedirs(d, exist_ok=True)
    content = base64.b64decode(enc).decode("utf-8")
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(content)
    print(f"FIXED  {path} ({len(content.splitlines())} lines)")

# Remove ALL temp fix scripts
removed = []
for pattern in ["fix_*.py","fix_*.sh","patch_*.sh","patch_*.py"]:
    for f in glob.glob(pattern):
        if f != "fix_final_clean.py":
            os.remove(f); removed.append(f)
for f in removed:
    print(f"REMOVED  {f}")

print("\n✅ All done.")
print("Next steps:")
print("  npm run build")
print("  git add -A")
print("  git commit -m \"fix: final clean build — all type errors, IDL, exports, configs\"")
print("  git push origin main")
